import { test, expect } from '@playwright/test';

test.describe('Delete Record Confirmation Modal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display confirmation modal when delete button is clicked', async ({ page }) => {
    // Click the delete button to trigger the modal
    await page.getByRole('button', { name: /delete/i }).click();

    // Verify the modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Verify modal contains confirmation message
    await expect(page.getByText(/are you sure/i)).toBeVisible();
  });

  test('should cancel deletion when cancel button is clicked', async ({ page }) => {
    // Click the delete button to trigger the modal
    await page.getByRole('button', { name: /delete/i }).click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Click cancel button
    await page.getByRole('button', { name: /cancel/i }).click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });

  test('should confirm deletion when confirm button is clicked', async ({ page }) => {
    // Get initial record count
    const recordsBefore = await page.getByRole('row').count();

    // Click the delete button to trigger the modal
    await page.getByRole('button', { name: /delete/i }).first().click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Click confirm button
    await page.getByRole('button', { name: /confirm|yes|delete/i }).click();

    // Verify modal is closed
    await expect(modal).not.toBeVisible();

    // Verify record was deleted (record count decreased)
    const recordsAfter = await page.getByRole('row').count();
    expect(recordsAfter).toBeLessThan(recordsBefore);
  });

  test('should display correct modal title and buttons', async ({ page }) => {
    // Click the delete button to trigger the modal
    await page.getByRole('button', { name: /delete/i }).click();

    // Verify modal title
    await expect(page.getByRole('heading', { name: /delete/i })).toBeVisible();

    // Verify confirm button exists
    await expect(page.getByRole('button', { name: /confirm|yes|delete/i })).toBeVisible();

    // Verify cancel button exists
    await expect(page.getByRole('button', { name: /cancel|no/i })).toBeVisible();
  });

  test('should close modal when clicking outside the modal', async ({ page }) => {
    // Click the delete button to trigger the modal
    await page.getByRole('button', { name: /delete/i }).click();

    // Verify modal is visible
    const modal = page.getByRole('dialog');
    await expect(modal).toBeVisible();

    // Click outside the modal (on the backdrop)
    await page.click('body', { position: { x: 10, y: 10 } });

    // Verify modal is closed
    await expect(modal).not.toBeVisible();
  });
});
